/**
 * FHIR Bundle Resource Schema
 * 
 * A Bundle is a container for a collection of resources.
 * In this dataset, each JSON file represents a single Bundle containing
 * all resources for one patient.
 * 
 * Key observations from the dataset:
 * - Type is always "transaction" (batch of resources to be processed)
 * - Each bundle contains exactly one Patient resource
 * - Bundles contain 31 to 22,049 entries (massive variation)
 * - Resources are linked via UUID references
 * - Entry count correlates with file size (0.1MB to 54.7MB)
 * - Common resource types: Observation, Claim, ExplanationOfBenefit, 
 *   MedicationRequest, DiagnosticReport, Procedure, Encounter, Condition
 */

// Bundle type enumeration
const BundleTypeSchema = z.enum([
  'document',
  'message', 
  'transaction',
  'transaction-response',
  'batch',
  'batch-response',
  'history',
  'searchset',
  'collection'
]);

// HTTP verb for bundle entries
const HTTPVerbSchema = z.enum([
  'GET',
  'HEAD',
  'POST',
  'PUT',
  'DELETE',
  'PATCH'
]);

// Bundle entry request information
const BundleEntryRequestSchema = z.object({
  method: HTTPVerbSchema,
  url: z.string(),
  ifNoneMatch: z.string().optional(),
  ifModifiedSince: InstantSchema.optional(),
  ifMatch: z.string().optional(),
  ifNoneExist: z.string().optional(),
});

// Bundle entry response information
const BundleEntryResponseSchema = z.object({
  status: z.string(),
  location: UriSchema.optional(),
  etag: z.string().optional(),
  lastModified: InstantSchema.optional(),
  outcome: z.any().optional(), // OperationOutcome resource
});

// Bundle entry search information
const BundleEntrySearchSchema = z.object({
  mode: z.enum(['match', 'include', 'outcome']).optional(),
  score: z.number().optional(),
});

// Generic resource schema - covers all possible resource types
const AnyResourceSchema = z.union([
  PatientSchema,
  ObservationSchema,
  EncounterSchema,
  ConditionSchema,
  // Allow any other resource types that might be present
  BaseResourceSchema.extend({
    resourceType: z.string(),
  }).passthrough(),
]);

// Bundle entry - represents a single resource in the bundle
const BundleEntrySchema = z.object({
  // Links related to this entry
  link: z.array(z.object({
    relation: z.string(),
    url: UriSchema,
  })).optional(),

  // Absolute URL for this entry
  fullUrl: z.string().optional(),

  // The resource in this entry
  resource: AnyResourceSchema.optional(),

  // Search related information
  search: BundleEntrySearchSchema.optional(),

  // Additional execution information for transaction/batch
  request: BundleEntryRequestSchema.optional(),

  // Results of executing the request
  response: BundleEntryResponseSchema.optional(),
});

/**
 * Bundle Resource
 * 
 * A container for a collection of resources.
 * Each JSON file in the dataset represents one Bundle.
 */
export const BundleSchema = BaseResourceSchema.extend({
  resourceType: z.literal('Bundle'),

  // Persistent identifier for the bundle
  identifier: z.object({
    system: UriSchema.optional(),
    value: z.string().optional(),
  }).optional(),

  // Type of bundle
  type: BundleTypeSchema,

  // When the bundle was assembled
  timestamp: InstantSchema.optional(),

  // Total number of matches (for search bundles)
  total: z.number().optional(),

  // Links related to this bundle
  link: z.array(z.object({
    relation: z.string(),
    url: UriSchema,
  })).optional(),

  // Entries in the bundle
  entry: z.array(BundleEntrySchema).optional(),

  // Digital signature
  signature: z.object({
    type: z.array(z.object({
      system: UriSchema,
      code: z.string(),
      display: z.string().optional(),
    })),
    when: InstantSchema,
    who: z.object({
      reference: z.string().optional(),
      display: z.string().optional(),
    }),
    onBehalfOf: z.object({
      reference: z.string().optional(),
      display: z.string().optional(),
    }).optional(),
    targetFormat: z.string().optional(),
    sigFormat: z.string().optional(),
    data: z.string().optional(),
  }).optional(),
});

export type Bundle = z.infer<typeof BundleSchema>;
export type BundleEntry = z.infer<typeof BundleEntrySchema>;
export type AnyResource = z.infer<typeof AnyResourceSchema>;

/**
 * Utility function to extract bundle summary
 * Useful for debugging and data analysis
 */
export function extractBundleSummary(bundle: Bundle) {
  const resourceTypeCounts: Record<string, number> = {};

  bundle.entry?.forEach(entry => {
    if (entry.resource) {
      const resourceType = entry.resource.resourceType;
      resourceTypeCounts[resourceType] = (resourceTypeCounts[resourceType] || 0) + 1;
    }
  });

  const patient = bundle.entry?.find(entry => entry.resource?.resourceType === 'Patient')?.resource;
  const patientName = patient && 'name' in patient ? patient.name?.[0] : null;
  const patientFullName = patientName ? 
    `${patientName.prefix?.[0] || ''} ${patientName.given?.join(' ') || ''} ${patientName.family || ''}`.trim() : 
    'Unknown';

  return {
    id: bundle.id,
    type: bundle.type,
    timestamp: bundle.timestamp,
    totalEntries: bundle.entry?.length || 0,
    resourceTypeCounts,
    patientName: patientFullName,
    patientId: patient?.id,
  };
}

/**
 * Utility function to get all resources of a specific type from a bundle
 */
export function getResourcesByType<T extends AnyResource>(
  bundle: Bundle, 
  resourceType: string
): T[] {
  return (bundle.entry || [])
    .map(entry => entry.resource)
    .filter((resource): resource is T => 
      resource?.resourceType === resourceType
    );
}

/**
 * Utility function to get the patient from a bundle
 */
export function getPatientFromBundle(bundle: Bundle) {
  return getResourcesByType(bundle, 'Patient')[0];
}

/**
 * Utility function to validate bundle structure
 */
export function validateBundleStructure(bundle: Bundle): {
  isValid: boolean;
  errors: string[];
} {
  const errors: string[] = [];

  // Check for required patient resource
  const patients = getResourcesByType(bundle, 'Patient');
  if (patients.length === 0) {
    errors.push('Bundle must contain exactly one Patient resource');
  } else if (patients.length > 1) {
    errors.push('Bundle contains multiple Patient resources');
  }

  // Check for resource references
  const patientId = patients[0]?.id;
  if (patientId) {
    const observationsWithoutPatientRef = getResourcesByType(bundle, 'Observation')
      .filter(obs => !obs.subject?.reference?.includes(patientId));

    if (observationsWithoutPatientRef.length > 0) {
      errors.push(`${observationsWithoutPatientRef.length} observations don't reference the patient`);
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
  };
}

