/**
 * FHIR Bundle Loader
 * 
 * Loads and validates FHIR bundles from JSON files.
 * Provides utility functions for reading, validating, and analyzing the healthcare data.
 */

export interface LoadResult {
  success: boolean;
  bundle?: Bundle;
  patient?: Patient;
  errors: string[];
  warnings: string[];
  stats: {
    fileName: string;
    fileSize: number;
    fileSizeMB: number;
    entryCount: number;
    resourceTypeCounts: Record<string, number>;
  };
}

export interface LoadOptions {
  validate?: boolean;
  includePatientSummary?: boolean;
  strict?: boolean;
}

/**
 * Load a single FHIR bundle from a JSON file
 */
export function loadFhirBundle(filePath: string, options: LoadOptions = {}): LoadResult {
  const {
    validate = true,
    includePatientSummary = true,
    strict = false
  } = options;

  const fileName = filePath.split('/').pop() || 'unknown';
  const errors: string[] = [];
  const warnings: string[] = [];

  try {
    // Read and parse the JSON file
    const fileStats = statSync(filePath);
    const fileSize = fileStats.size;
    const fileSizeMB = Math.round(fileSize / (1024 * 1024) * 10) / 10;

    const jsonContent = readFileSync(filePath, 'utf-8');
    const rawData = JSON.parse(jsonContent);

    // Validate with Zod schema
    let bundle: Bundle;
    try {
      bundle = BundleSchema.parse(rawData);
    } catch (zodError: any) {
      if (strict) {
        return {
          success: false,
          errors: [`Schema validation failed: ${zodError.message}`],
          warnings,
          stats: {
            fileName,
            fileSize,
            fileSizeMB,
            entryCount: 0,
            resourceTypeCounts: {},
          }
        };
      } else {
        // In non-strict mode, try to work with the data anyway
        warnings.push(`Schema validation failed, proceeding anyway: ${zodError.message}`);
        bundle = rawData as Bundle;
      }
    }

    // Extract statistics
    const bundleSummary = extractBundleSummary(bundle);
    const entryCount = bundle.entry?.length || 0;

    // Validate bundle structure
    if (validate) {
      const structureValidation = validateBundleStructure(bundle);
      if (!structureValidation.isValid) {
        errors.push(...structureValidation.errors);
      }
    }

    // Extract patient information
    let patient: Patient | undefined;
    if (includePatientSummary) {
      patient = getPatientFromBundle(bundle);
      if (!patient) {
        errors.push('No patient resource found in bundle');
      }
    }

    return {
      success: errors.length === 0,
      bundle,
      patient,
      errors,
      warnings,
      stats: {
        fileName,
        fileSize,
        fileSizeMB,
        entryCount,
        resourceTypeCounts: bundleSummary.resourceTypeCounts,
      }
    };

  } catch (error: any) {
    return {
      success: false,
      errors: [`Failed to load file: ${error.message}`],
      warnings,
      stats: {
        fileName,
        fileSize: 0,
        fileSizeMB: 0,
        entryCount: 0,
        resourceTypeCounts: {},
      }
    };
  }
}

/**
 * Load multiple FHIR bundles from a directory
 */
export function loadFhirBundles(
  directoryPath: string, 
  options: LoadOptions & { limit?: number } = {}
): LoadResult[] {
  const { limit, ...loadOptions } = options;

  try {
    const files = readdirSync(directoryPath)
      .filter(file => file.endsWith('.json'))
      .slice(0, limit);

    return files.map(fileName => {
      const filePath = join(directoryPath, fileName);
      return loadFhirBundle(filePath, loadOptions);
    });

  } catch (error: any) {
    return [{
      success: false,
      errors: [`Failed to read directory: ${error.message}`],
      warnings: [],
      stats: {
        fileName: 'directory',
        fileSize: 0,
        fileSizeMB: 0,
        entryCount: 0,
        resourceTypeCounts: {},
      }
    }];
  }
}

/**
 * Analyze a directory of FHIR bundles and return aggregate statistics
 */
export function analyzeFhirDirectory(directoryPath: string, sampleSize: number = 50) {
  const results = loadFhirBundles(directoryPath, { limit: sampleSize });

  const successfulLoads = results.filter(r => r.success);
  const failedLoads = results.filter(r => !r.success);

  const totalEntries = successfulLoads.reduce((sum, r) => sum + r.stats.entryCount, 0);
  const totalSizeMB = successfulLoads.reduce((sum, r) => sum + r.stats.fileSizeMB, 0);

  const aggregatedResourceCounts: Record<string, number> = {};
  successfulLoads.forEach(result => {
    Object.entries(result.stats.resourceTypeCounts).forEach(([type, count]) => {
      aggregatedResourceCounts[type] = (aggregatedResourceCounts[type] || 0) + count;
    });
  });

  const fileSizes = successfulLoads.map(r => r.stats.fileSizeMB);
  const entryCounts = successfulLoads.map(r => r.stats.entryCount);

  return {
    summary: {
      totalFiles: results.length,
      successfulLoads: successfulLoads.length,
      failedLoads: failedLoads.length,
      totalEntries,
      totalSizeMB,
      avgEntriesPerFile: totalEntries / successfulLoads.length,
      avgSizeMBPerFile: totalSizeMB / successfulLoads.length,
    },

    distributionStats: {
      fileSizes: {
        min: Math.min(...fileSizes),
        max: Math.max(...fileSizes),
        median: fileSizes.sort()[Math.floor(fileSizes.length / 2)],
      },
      entryCounts: {
        min: Math.min(...entryCounts),
        max: Math.max(...entryCounts),
        median: entryCounts.sort()[Math.floor(entryCounts.length / 2)],
      },
    },

    resourceTypeDistribution: Object.entries(aggregatedResourceCounts)
      .sort(([, a], [, b]) => b - a)
      .reduce((acc, [type, count]) => {
        acc[type] = {
          count,
          percentage: (count / totalEntries) * 100,
        };
        return acc;
      }, {} as Record<string, { count: number; percentage: number }>),

    errors: failedLoads.flatMap(r => r.errors),
    warnings: results.flatMap(r => r.warnings),

    patientSummaries: successfulLoads
      .map(r => r.patient ? extractPatientSummary(r.patient) : null)
      .filter(Boolean),
  };
}

/**
 * Utility function to get sample data for testing
 */
export function getSampleBundles(directoryPath: string, count: number = 3) {
  const files = readdirSync(directoryPath)
    .filter(file => file.endsWith('.json'));

  // Get small, medium, and large files
  const fileStats = files.map(file => ({
    name: file,
    size: statSync(join(directoryPath, file)).size,
  })).sort((a, b) => a.size - b.size);

  const sampleFiles = [
    fileStats[0], // smallest
    fileStats[Math.floor(fileStats.length / 2)], // median
    fileStats[fileStats.length - 1], // largest
  ].slice(0, count);

  return sampleFiles.map(file => 
    loadFhirBundle(join(directoryPath, file.name))
  );
}

