import { readdirSync } from 'fs';
import { join } from 'path';
import { loadFhirBundle } from '../loaders/fhir-loader';
import { 
  BundleSchema, 
  PatientSchema, 
  ObservationSchema, 
  EncounterSchema, 
  ConditionSchema,
  getResourcesByType,
  extractBundleSummary,
  ValidationPatterns
} from '../schema';

/**
 * Comprehensive Schema Validation
 * 
 * This script performs extensive validation of the schemas against
 * a larger sample of the dataset to identify edge cases and improve
 * schema coverage.
 */

const DATA_PATH = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface ValidationStats {
  totalFiles: number;
  validatedFiles: number;
  failedFiles: number;
  resourceValidation: {
    patients: { validated: number; failed: number };
    observations: { validated: number; failed: number };
    encounters: { validated: number; failed: number };
    conditions: { validated: number; failed: number };
    others: { validated: number; failed: number };
  };
  patternValidation: {
    uuids: { total: number; valid: number };
    dates: { total: number; valid: number };
    datetimes: { total: number; valid: number };
    synthea_names: { total: number; valid: number };
  };
  uniqueValues: {
    resourceTypes: Set<string>;
    genders: Set<string>;
    observationStatuses: Set<string>;
    encounterStatuses: Set<string>;
  };
  errors: string[];
  warnings: string[];
}

export function runComprehensiveValidation(sampleSize: number = 100): ValidationStats {
  const files = readdirSync(DATA_PATH).filter(f => f.endsWith('.json')).slice(0, sampleSize);

  const stats: ValidationStats = {
    totalFiles: files.length,
    validatedFiles: 0,
    failedFiles: 0,
    resourceValidation: {
      patients: { validated: 0, failed: 0 },
      observations: { validated: 0, failed: 0 },
      encounters: { validated: 0, failed: 0 },
      conditions: { validated: 0, failed: 0 },
      others: { validated: 0, failed: 0 },
    },
    patternValidation: {
      uuids: { total: 0, valid: 0 },
      dates: { total: 0, valid: 0 },
      datetimes: { total: 0, valid: 0 },
      synthea_names: { total: 0, valid: 0 },
    },
    uniqueValues: {
      resourceTypes: new Set(),
      genders: new Set(),
      observationStatuses: new Set(),
      encounterStatuses: new Set(),
    },
    errors: [],
    warnings: [],
  };

  console.log(`🔍 Running comprehensive validation on ${files.length} files...\n`);

  for (const [index, fileName] of files.entries()) {
    if (index % 10 === 0) {
      console.log(`Progress: ${index}/${files.length} files (${Math.round(index/files.length*100)}%)`);
    }

    const filePath = join(DATA_PATH, fileName);
    const result = loadFhirBundle(filePath, { validate: true, strict: false });

    if (!result.success || !result.bundle) {
      stats.failedFiles++;
      stats.errors.push(`${fileName}: ${result.errors.join(', ')}`);
      continue;
    }

    stats.validatedFiles++;
    stats.warnings.push(...result.warnings.map(w => `${fileName}: ${w}`));

    const bundle = result.bundle;

    // Validate individual resources
    bundle.entry?.forEach(entry => {
      if (!entry.resource) return;

      const resourceType = entry.resource.resourceType;
      stats.uniqueValues.resourceTypes.add(resourceType);

      try {
        switch (resourceType) {
          case 'Patient':
            PatientSchema.parse(entry.resource);
            stats.resourceValidation.patients.validated++;

            // Collect gender values
            if ('gender' in entry.resource && entry.resource.gender) {
              stats.uniqueValues.genders.add(entry.resource.gender);
            }

            // Validate name patterns
            if ('name' in entry.resource && entry.resource.name) {
              entry.resource.name.forEach(name => {
                if (name.given) {
                  name.given.forEach(given => {
                    stats.patternValidation.synthea_names.total++;
                    if (ValidationPatterns.SYNTHEA_NAME.test(given)) {
                      stats.patternValidation.synthea_names.valid++;
                    }
                  });
                }
                if (name.family) {
                  stats.patternValidation.synthea_names.total++;
                  if (ValidationPatterns.SYNTHEA_NAME.test(name.family)) {
                    stats.patternValidation.synthea_names.valid++;
                  }
                }
              });
            }

            // Validate birth date
            if ('birthDate' in entry.resource && entry.resource.birthDate) {
              stats.patternValidation.dates.total++;
              if (ValidationPatterns.ISO_DATE.test(entry.resource.birthDate)) {
                stats.patternValidation.dates.valid++;
              }
            }
            break;

          case 'Observation':
            ObservationSchema.parse(entry.resource);
            stats.resourceValidation.observations.validated++;

            // Collect status values
            if ('status' in entry.resource && entry.resource.status) {
              stats.uniqueValues.observationStatuses.add(entry.resource.status);
            }

            // Validate datetime
            if ('effectiveDateTime' in entry.resource && entry.resource.effectiveDateTime) {
              stats.patternValidation.datetimes.total++;
              if (ValidationPatterns.ISO_DATETIME.test(entry.resource.effectiveDateTime)) {
                stats.patternValidation.datetimes.valid++;
              }
            }
            break;

          case 'Encounter':
            EncounterSchema.parse(entry.resource);
            stats.resourceValidation.encounters.validated++;

            // Collect status values
            if ('status' in entry.resource && entry.resource.status) {
              stats.uniqueValues.encounterStatuses.add(entry.resource.status);
            }
            break;

          case 'Condition':
            ConditionSchema.parse(entry.resource);
            stats.resourceValidation.conditions.validated++;
            break;

          default:
            // Try to validate as generic resource
            BundleSchema.shape.entry.element.shape.resource.parse(entry.resource);
            stats.resourceValidation.others.validated++;
            break;
        }

        // Validate UUID in resource ID
        if (entry.resource.id) {
          stats.patternValidation.uuids.total++;
          if (ValidationPatterns.UUID.test(entry.resource.id)) {
            stats.patternValidation.uuids.valid++;
          }
        }

      } catch (error: any) {
        switch (resourceType) {
          case 'Patient':
            stats.resourceValidation.patients.failed++;
            break;
          case 'Observation':
            stats.resourceValidation.observations.failed++;
            break;
          case 'Encounter':
            stats.resourceValidation.encounters.failed++;
            break;
          case 'Condition':
            stats.resourceValidation.conditions.failed++;
            break;
          default:
            stats.resourceValidation.others.failed++;
            break;
        }

        stats.errors.push(`${fileName} - ${resourceType}: ${error.message}`);
      }
    });
  }

  console.log('\n📊 Comprehensive Validation Results:');
  console.log(`\n📁 File Results:`);
  console.log(`  ✓ ${stats.validatedFiles}/${stats.totalFiles} files loaded successfully`);
  console.log(`  ✗ ${stats.failedFiles}/${stats.totalFiles} files failed to load`);

  console.log(`\n🔍 Resource Validation:`);
  Object.entries(stats.resourceValidation).forEach(([type, counts]) => {
    const total = counts.validated + counts.failed;
    if (total > 0) {
      console.log(`  ${type}: ${counts.validated}/${total} validated (${Math.round(counts.validated/total*100)}%)`);
    }
  });

  console.log(`\n🎯 Pattern Validation:`);
  Object.entries(stats.patternValidation).forEach(([pattern, counts]) => {
    if (counts.total > 0) {
      console.log(`  ${pattern}: ${counts.valid}/${counts.total} valid (${Math.round(counts.valid/counts.total*100)}%)`);
    }
  });

  console.log(`\n📈 Unique Values Found:`);
  console.log(`  Resource Types: ${Array.from(stats.uniqueValues.resourceTypes).join(', ')}`);
  console.log(`  Genders: ${Array.from(stats.uniqueValues.genders).join(', ')}`);
  console.log(`  Observation Statuses: ${Array.from(stats.uniqueValues.observationStatuses).join(', ')}`);
  console.log(`  Encounter Statuses: ${Array.from(stats.uniqueValues.encounterStatuses).join(', ')}`);

  if (stats.errors.length > 0) {
    console.log(`\n⚠️  First 10 Errors:`);
    stats.errors.slice(0, 10).forEach(error => console.log(`  - ${error}`));
    if (stats.errors.length > 10) {
      console.log(`  ... and ${stats.errors.length - 10} more errors`);
    }
  }

  if (stats.warnings.length > 0) {
    console.log(`\n⚠️  First 5 Warnings:`);
    stats.warnings.slice(0, 5).forEach(warning => console.log(`  - ${warning}`));
    if (stats.warnings.length > 5) {
      console.log(`  ... and ${stats.warnings.length - 5} more warnings`);
    }
  }

  return stats;
}

// Run the comprehensive validation if this file is executed directly
if (require.main === module) {
  const sampleSize = process.argv[2] ? parseInt(process.argv[2]) : 50;
  runComprehensiveValidation(sampleSize);
}

